// Always returns exactly one item so the IF node after it can decide.
const first = $input.first();
const res = (first && first.json && first.json.esearchresult) || {};
const ids = Array.isArray(res.idlist) ? res.idlist : [];
return [{ json: { ids: ids.join(','), count: ids.length } }];

const first = $input.first();
const root = (first && first.json) || {};
const set = root.PubmedArticleSet;
let articles = (set && set.PubmedArticle) || [];
if (!Array.isArray(articles)) articles = [articles];

function textOf(node) {
  if (node === undefined || node === null) return '';
  if (typeof node === 'string') return node;
  if (Array.isArray(node)) return node.map(textOf).join(' ');
  if (typeof node === 'object') return textOf(node._ || node['#text'] || '');
  return String(node);
}
function pad(n) { return String(n).padStart(2, '0'); }

const out = [];
for (const a of articles) {
  const medline = a.MedlineCitation || {};
  const article = medline.Article || {};
  const pmid = textOf(medline.PMID).trim();
  if (!pmid) continue;
  const title = textOf(article.ArticleTitle).trim() || '(no title)';
  const abstract = textOf(article.Abstract && article.Abstract.AbstractText).trim();
  const journal = article.Journal && article.Journal.Title ? textOf(article.Journal.Title).trim() : '';

  let date = '';
  const ad = Array.isArray(article.ArticleDate) ? article.ArticleDate[0] : article.ArticleDate;
  if (ad && ad.Year) {
    date = [textOf(ad.Year), pad(textOf(ad.Month) || '1'), pad(textOf(ad.Day) || '1')].join('-');
  } else {
    const pd = article.Journal && article.Journal.JournalIssue && article.Journal.JournalIssue.PubDate;
    date = pd ? (textOf(pd.Year) || textOf(pd.MedlineDate).slice(0, 4)) : '';
  }

  out.push({
    json: {
      source: 'PubMed',
      sourceType: 'literature',
      title,
      journal,
      date,
      link: 'https://pubmed.ncbi.nlm.nih.gov/' + pmid + '/',
      text: title + '. ' + abstract
    }
  });
}
return out;

const first = $input.first();
const body = (first && first.json) || {};
const hits = (body.hits && body.hits.hits) || [];

return hits.map(h => {
  const md = h.metadata || {};
  const desc = String(md.description || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  const creators = (md.creators || []).map(c => c.name).slice(0, 3).join(', ');
  const title = String(md.title || '(no title)').trim();
  return {
    json: {
      source: 'Zenodo',
      sourceType: 'literature',
      title,
      journal: creators,
      date: md.publication_date || '',
      link: (h.links && (h.links.self_html || h.links.html)) || '',
      text: title + '. ' + desc
    }
  };
});

const first = $input.first();
const data = (first && first.json) || {};
const results = (data.response && data.response.results) || [];

function cleanHtml(value) {
  return String(value || '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

return results
  .filter(a => a.type === 'article')
  .map(a => {
    const f = a.fields || {};
    const title = cleanHtml(f.headline || a.webTitle || '(no title)');
    const body = cleanHtml(f.body || f.trailText || '');
    return {
      json: {
        source: 'The Guardian',
        sourceType: 'news',
        title,
        journal: 'The Guardian',
        date: String(a.webPublicationDate || '').slice(0, 10),
        link: a.webUrl || '',
        text: (title + '. ' + body).trim(),
        section: a.sectionName || ''
      }
    };
  });

// Fallback list, used only if vocab.json could not be loaded from GitHub.
const FALLBACK = {
  strongWords: ['delve', 'delves', 'delving', 'tapestry', 'intricate', 'intricacies', 'meticulous', 'meticulously', 'underscore', 'underscores', 'underscoring', 'showcasing', 'commendable', 'multifaceted', 'myriad', 'plethora', 'testament'],
  weakWords: ['pivotal', 'crucial', 'robust', 'comprehensive', 'notably', 'furthermore', 'moreover', 'leverage', 'leveraging', 'foster', 'fostering', 'paradigm', 'holistic', 'landscape'],
  explicitPhrases: ['as an ai language model', 'as a large language model', 'as an ai assistant', 'regenerate response', 'as of my last knowledge update'],
  weights: { strong: 2, weak: 0.5 },
  thresholds: { minWords: 80, minStrongHits: 2, moderate: 1.5, elevated: 3.0, detectorHigh: 85 }
};

let vocab = FALLBACK;
try {
  const v = $('Load vocab.json').first().json;
  if (v && Array.isArray(v.strongWords) && v.thresholds && v.weights) vocab = v;
} catch (e) { /* keep fallback */ }

function scoreText(rawText, vocab) {
  const text = String(rawText || '');
  const lower = text.toLowerCase();
  const wordCount = text.trim() ? text.trim().split(/\s+/).length : 0;
  const t = vocab.thresholds;
  const matched = {};
  let strongHits = 0;
  let weakHits = 0;

  function countWords(list, isStrong) {
    for (const w of list) {
      const re = new RegExp('(?<![\\w-])' + w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(?![\\w-])', 'gi');
      const n = (text.match(re) || []).length;
      if (n > 0) {
        matched[w] = (matched[w] || 0) + n;
        if (isStrong) strongHits += n; else weakHits += n;
      }
    }
  }
  countWords(vocab.strongWords, true);
  countWords(vocab.weakWords, false);

  let explicitHit = null;
  for (const p of vocab.explicitPhrases) {
    if (lower.includes(p)) { explicitHit = p; break; }
  }

  const weighted = wordCount > 0
    ? ((strongHits * vocab.weights.strong + weakHits * vocab.weights.weak) / wordCount) * 100
    : 0;

  let level = 'none';
  const tooShort = wordCount < t.minWords;
  const strongOk = strongHits >= (t.minStrongHits || 1);
  if (explicitHit) level = 'explicit';
  else if (!tooShort && strongOk && weighted >= t.elevated) level = 'elevated';
  else if (!tooShort && strongOk && weighted >= t.moderate) level = 'moderate';

  const top = Object.entries(matched).sort((a, b) => b[1] - a[1]).slice(0, 8)
    .map(([w, n]) => (n > 1 ? w + ' x' + n : w));

  return {
    words: wordCount,
    tooShort,
    strongHits,
    weakHits,
    weighted: Number(weighted.toFixed(2)),
    level,
    explicitHit,
    matched: top
  };
}


const seen = new Set();
const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (!j.link || !j.text) continue;
  if (seen.has(j.link)) continue;
  seen.add(j.link);
  const s = scoreText(j.text, vocab);
  out.push({
    json: {
      ...j,
      words: s.words,
      tooShort: s.tooShort,
      vocabLevel: s.level,
      vocabWeighted: s.weighted,
      vocabStrong: s.strongHits,
      vocabWeak: s.weakHits,
      matched: s.matched,
      explicitHit: s.explicitHit,
      detThreshold: vocab.thresholds.detectorHigh
    }
  });
}
return out;

// Decide which items are worth one detector call, within the daily budget.
// Priority: vocabulary-flagged items first, then a round-robin sample across sources
// so one source (e.g. the Guardian) cannot use up the whole budget.
const cfg = $('Config').first().json || {};
const max = Math.max(0, Number(cfg.maxDetectorCalls) || 10);

let history = {};
try { history = $('Load history').first().json || {}; } catch (e) { history = {}; }
const checked = new Set(
  (Array.isArray(history.items) ? history.items : [])
    .filter(i => i && i.detectorScore !== undefined && i.detectorScore !== null)
    .map(i => i.link)
);

const rank = { elevated: 3, moderate: 2, none: 1 };
const cands = $input.all()
  .map(i => i.json)
  .filter(j => j && j.link && !j.tooShort && j.vocabLevel !== 'explicit' && !checked.has(j.link));

const byStrength = (a, b) => (rank[b.vocabLevel] - rank[a.vocabLevel]) || (b.vocabWeighted - a.vocabWeighted);

const flagged = cands.filter(j => rank[j.vocabLevel] > 1).sort(byStrength);

const groups = {};
cands.filter(j => rank[j.vocabLevel] === 1).forEach(j => {
  (groups[j.source] = groups[j.source] || []).push(j);
});
Object.values(groups).forEach(g => g.sort(byStrength));

const rest = [];
let added = true;
while (added) {
  added = false;
  for (const k of Object.keys(groups)) {
    const next = groups[k].shift();
    if (next) { rest.push(next); added = true; }
  }
}

const selected = flagged.concat(rest).slice(0, max);
if (selected.length === 0) return [{ json: { _skip: true } }];
return selected.map(j => ({ json: j }));

// Attach detector scores to the scored items and compute the final tier.
// Input is either the Sapling responses (same order as the selected items) or the "nothing to check" marker.
const selected = $('Select For Detector').all().map(i => i.json).filter(j => j && !j._skip);
const responses = $input.all().map(i => i.json || {});

const scoreByLink = {};
let detectorErrors = 0;
if (selected.length > 0) {
  if (responses.length !== selected.length) {
    detectorErrors = selected.length;
  } else {
    selected.forEach((j, idx) => {
      const r = responses[idx];
      const n = Number(r && r.score);
      if (r && !r.error && r.score !== undefined && r.score !== null && Number.isFinite(n)) {
        scoreByLink[j.link] = Math.round(n * 100);
      } else {
        detectorErrors++;
      }
    });
  }
}

const out = [];
for (const it of $('Prepare & Score').all()) {
  const j = it.json || {};
  if (!j.link) continue;
  const detectorScore = Object.prototype.hasOwnProperty.call(scoreByLink, j.link) ? scoreByLink[j.link] : null;
  const detHigh = detectorScore !== null && detectorScore >= (j.detThreshold || 85);
  const vocabFlag = j.vocabLevel === 'moderate' || j.vocabLevel === 'elevated' || j.vocabLevel === 'explicit';

  let signal = 'none';
  if (j.vocabLevel === 'explicit' || (vocabFlag && detHigh)) signal = 'strong';
  else if (vocabFlag || detHigh) signal = 'weak';

  const reasons = [];
  if (j.explicitHit) reasons.push('Leftover chatbot phrase: "' + j.explicitHit + '"');
  if (j.vocabLevel === 'moderate' || j.vocabLevel === 'elevated') {
    reasons.push('Vocabulary drift (' + j.vocabLevel + '): ' + j.vocabStrong + ' strong word(s), weighted density ' + j.vocabWeighted + ' per 100 words');
  }
  if (detectorScore !== null) reasons.push('Detector score ' + detectorScore + '/100');

  out.push({
    json: {
      source: j.source,
      sourceType: j.sourceType,
      title: j.title,
      journal: j.journal,
      date: j.date,
      link: j.link,
      words: j.words,
      vocabLevel: j.vocabLevel,
      vocabWeighted: j.vocabWeighted,
      matched: j.matched,
      explicitHit: j.explicitHit,
      detectorScore,
      detectorProvider: detectorScore !== null ? 'Sapling' : null,
      signal,
      reasons
    }
  });
}

out.push({ json: { _meta: true, detectorChecked: Object.keys(scoreByLink).length, detectorErrors } });
return out;

// Merge today's results into the history file, update run statistics, and build the email.
const all = $input.all().map(i => i.json || {});
const meta = all.find(j => j._meta) || { detectorChecked: 0, detectorErrors: 0 };
const scored = all.filter(j => j.link);

const cfg = $('Config').first().json || {};
const retentionDays = Number(cfg.retentionDays) || 90;
const today = new Date().toISOString().slice(0, 10);
const cutoff = new Date(Date.now() - retentionDays * 86400000).toISOString().slice(0, 10);

let hist = {};
try { hist = $('Load history').first().json || {}; } catch (e) { hist = {}; }
const oldItems = Array.isArray(hist.items) ? hist.items : [];
const oldRuns = Array.isArray(hist.runs) ? hist.runs : [];

// Only keep items that carry a signal or were checked by the detector.
// Items with no signal and no detector score are counted but not listed.
const keepNew = scored.filter(j => j.signal !== 'none' || j.detectorScore !== null);

const byLink = new Map();
oldItems.forEach(i => { if (i && i.link) byLink.set(i.link, i); });
keepNew.forEach(j => {
  if (!byLink.has(j.link)) byLink.set(j.link, { ...j, firstSeen: today });
});

const rank = { strong: 3, weak: 2, none: 1 };
const items = Array.from(byLink.values())
  .filter(i => (i.firstSeen || today) >= cutoff)
  .sort((a, b) =>
    (rank[b.signal] - rank[a.signal]) ||
    ((b.detectorScore ?? -1) - (a.detectorScore ?? -1)) ||
    String(b.firstSeen).localeCompare(String(a.firstSeen))
  );

const bySource = {};
scored.forEach(j => { bySource[j.source] = (bySource[j.source] || 0) + 1; });

const run = {
  date: today,
  scanned: scored.length,
  bySource,
  vocabFlagged: scored.filter(j => j.vocabLevel !== 'none').length,
  detectorChecked: meta.detectorChecked,
  detectorErrors: meta.detectorErrors,
  strong: items.filter(i => i.firstSeen === today && i.signal === 'strong').length,
  weak: items.filter(i => i.firstSeen === today && i.signal === 'weak').length
};

const runs = oldRuns.filter(r => r && r.date !== today).concat([run]).slice(-retentionDays);

const file = {
  schema: 2,
  generatedAt: new Date().toISOString(),
  lastRun: run,
  runs,
  items
};
const fileContent = JSON.stringify(file, null, 1);

// ---------- Email ----------
function esc(s) {
  return String(s === undefined || s === null ? '' : s).replace(/[&<>"']/g, m => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]));
}
const todays = items.filter(i => i.firstSeen === today && i.signal !== 'none');
const checkedToday = keepNew.filter(j => j.detectorScore !== null).sort((a, b) => b.detectorScore - a.detectorScore).slice(0, 10);

function row(i) {
  const tier = i.signal === 'strong' ? 'STRONG' : i.signal === 'weak' ? 'WEAK' : 'NONE';
  const col = i.signal === 'strong' ? '#B3261E' : i.signal === 'weak' ? '#9A6A0C' : '#1F6E63';
  return '<tr>' +
    '<td style="padding:6px 8px;border-bottom:1px solid #ddd;color:' + col + ';font-weight:600">' + tier + '</td>' +
    '<td style="padding:6px 8px;border-bottom:1px solid #ddd"><a href="' + esc(i.link) + '">' + esc(i.title) + '</a><br><span style="color:#666;font-size:12px">' + esc(i.source) + '</span></td>' +
    '<td style="padding:6px 8px;border-bottom:1px solid #ddd;text-align:right">' + (i.detectorScore !== null && i.detectorScore !== undefined ? i.detectorScore + '/100' : '-') + '</td>' +
    '<td style="padding:6px 8px;border-bottom:1px solid #ddd;text-align:right">' + esc(i.vocabWeighted) + '</td>' +
    '</tr>';
}
function table(list) {
  return '<table style="border-collapse:collapse;width:100%;font-size:14px"><tr style="text-align:left;color:#555">' +
    '<th style="padding:6px 8px">Signal</th><th style="padding:6px 8px">Article</th>' +
    '<th style="padding:6px 8px;text-align:right">Detector</th><th style="padding:6px 8px;text-align:right">Vocab /100w</th></tr>' +
    list.map(row).join('') + '</table>';
}

let html = '<div style="font-family:Arial,sans-serif;max-width:720px;color:#1B2430">' +
  '<h2 style="margin:0 0 8px">Redline Watch - ' + esc(today) + '</h2>' +
  '<p style="margin:0 0 12px">' + run.scanned + ' records scanned (' + Object.keys(bySource).map(k => esc(k) + ' ' + bySource[k]).join(', ') + '). ' +
  run.detectorChecked + ' sent to the detector' + (run.detectorErrors ? ' (' + run.detectorErrors + ' detector errors)' : '') + '. ' +
  run.strong + ' strong and ' + run.weak + ' weak signals today.</p>';

if (run.scanned === 0) {
  html += '<p style="color:#B3261E"><b>No records were scanned.</b> A source or the search query is probably failing. Check the n8n execution log.</p>';
}
if (todays.length) html += '<h3>Flagged today</h3>' + table(todays);
else html += '<p>No flagged articles today.</p>';
if (checkedToday.length) html += '<h3>Highest detector scores today (all checked)</h3>' + table(checkedToday);

html += '<p style="margin-top:18px"><a href="https://ramiabouaziz.github.io/AI-Articles/redline-watch.html">Open the dashboard</a></p>' +
  '<p style="color:#666;font-size:12px">A detector score is a model estimate for the text it was given. It is not the share of the text written by AI, and detectors produce false positives, especially on short, formulaic or non-native English text. These are leads for a human reviewer, not proof of authorship.</p></div>';

const subject = 'Redline Watch - ' + (run.strong + run.weak) + ' flagged, ' + run.detectorChecked + ' checked of ' + run.scanned + ' scanned (' + today + ')';

return [{ json: { fileContent, subject, html, flaggedToday: todays.length, scanned: run.scanned } }];
